Q: JSON.NET Error Self referencing loop detected for type A: <p>I was facing the same problem and I tried using JsonSetting to ignore the self-referencing error its kinda work until I got a class which self-referencing very deeply and my dot-net process hangs on Json writing value.</p>
<p><strong>My Problem</strong></p>
<pre><code>    public partial class Company : BaseModel
{
    public Company()
    {
        CompanyUsers = new HashSet&lt;CompanyUser&gt;();
    }

    public string Name { get; set; }

    public virtual ICollection&lt;CompanyUser&gt; CompanyUsers { get; set; }
}

public partial class CompanyUser
{
    public int Id { get; set; }
    public int CompanyId { get; set; }
    public int UserId { get; set; }

    public virtual Company Company { get; set; }

    public virtual User User { get; set; }
}

public partial class User : BaseModel
{
    public User()
    {
        CompanyUsers = new HashSet&lt;CompanyUser&gt;();
    }

    public string DisplayName { get; set; }
    public virtual ICollection&lt;CompanyUser&gt; CompanyUsers { get; set; }

}
</code></pre>
<p>You can see the problem in User class it's referencing to <strong>CompanyUser</strong> class which is a self-referencing.</p>
<p>Now, I'm calling the GetAll Method which includes all the relational properties.</p>
<pre><code>cs.GetAll(&quot;CompanyUsers&quot;, &quot;CompanyUsers.User&quot;);
</code></pre>
<p>On this stage my DotNetCore process hangs on <strong>Executing JsonResult, writing value ...</strong> and never come. In my Startup.cs, I've already set the JsonOption. For some reason EFCore is including nested property which I'm not asking Ef to give.</p>
<pre><code>    options.SerializerSettings.ReferenceLoopHandling = Newtonsoft.Json.ReferenceLoopHandling.Ignore;
</code></pre>
<p>expected behavior should be this</p>
<blockquote>
<p>Hey EfCore can you please include &quot;CompanyUsers&quot; data as well in my
Company class so that I can easily access the data.</p>
</blockquote>
<p>then</p>
<blockquote>
<p>Hey EfCore can you also please include the <strong>&quot;CompanyUsers.User&quot;</strong> data as
well so that I can easily access the data like this
<strong>Company.CompanyUsers.First().User.DisplayName</strong></p>
</blockquote>
<p>At this stage I should only get this <strong>&quot;Company.CompanyUsers.First().User.DisplayName&quot;</strong> and it should not give me <strong>Company.CompanyUsers.First().User.CompanyUsers</strong> which causing the self-referencing issue; Technically it shouldn't give me <strong>User.CompanyUsers</strong> as CompanyUsers is a navigational property. But, EfCore get very excited and giving me <strong>User.CompanyUsers</strong>.</p>
<p>So, I decided to write an extension method for property to be excluded from the object (it's actually not excluding it's just setting the property to null). Not only that it will also work on array properties as well. Below is the code I'm also going to export the nuget package for other users. Reason is simple because I'm too lazy to write <strong>.Select(n =&gt; new { n.p1, n.p2});</strong> I just don't want to write select statement to exclude only 1 property!</p>
<p>This is not the best code (I'll update at some stage) as I have written in a hurry and though this might help someone who wants to exclude (set null) in the object with arrays also.</p>
<pre><code>    public static class PropertyExtensions
{
    public static void Exclude&lt;T&gt;(this T obj, Expression&lt;Func&lt;T, object&gt;&gt; expression)
    {
        var visitor = new PropertyVisitor&lt;T&gt;();
        visitor.Visit(expression.Body);
        visitor.Path.Reverse();
        List&lt;MemberInfo&gt; paths = visitor.Path;
        Action&lt;List&lt;MemberInfo&gt;, object&gt; act = null;

        int recursiveLevel = 0;
        act = (List&lt;MemberInfo&gt; vPath, object vObj) =&gt;
        {

            // set last propert to null thats what we want to avoid the self-referencing error.
            if (recursiveLevel == vPath.Count - 1)
            {
                if (vObj == null) throw new ArgumentNullException(&quot;Object cannot be null&quot;);

                vObj.GetType().GetMethod($&quot;set_{vPath.ElementAt(recursiveLevel).Name}&quot;).Invoke(vObj, new object[] { null });
                return;
            }

            var pi = vObj.GetType().GetProperty(vPath.ElementAt(recursiveLevel).Name);
            if (pi == null) return;
            var pv = pi.GetValue(vObj, null);
            if (pi.PropertyType.IsArray || pi.PropertyType.Name.Contains(&quot;HashSet`1&quot;) || pi.PropertyType.Name.Contains(&quot;ICollection`1&quot;))
            {
                var ele = (IEnumerator)pv.GetType().GetMethod(&quot;GetEnumerator&quot;).Invoke(pv, null);

                while (ele.MoveNext())
                {
                    recursiveLevel++;
                    var arrItem = ele.Current;

                    act(vPath, arrItem);

                    recursiveLevel--;
                }

                if (recursiveLevel != 0) recursiveLevel--;
                return;
            }
            else
            {
                recursiveLevel++;
                act(vPath, pv);
            }

            if (recursiveLevel != 0) recursiveLevel--;

        };

        // check if the root level propert is array
        if (obj.GetType().IsArray)
        {
            var ele = (IEnumerator)obj.GetType().GetMethod(&quot;GetEnumerator&quot;).Invoke(obj, null);
            while (ele.MoveNext())
            {
                recursiveLevel = 0;
                var arrItem = ele.Current;

                act(paths, arrItem);
            }
        }
        else
        {
            recursiveLevel = 0;
            act(paths, obj);
        }

    }

    public static T Explode&lt;T&gt;(this T[] obj)
    {
        return obj.FirstOrDefault();
    }

    public static T Explode&lt;T&gt;(this ICollection&lt;T&gt; obj)
    {
        return obj.FirstOrDefault();
    }
}
</code></pre>
<p>above extension class will give you the ability to set the property to null to avoid the self-referencing loop even arrays.</p>
<p><strong>Expression Builder</strong></p>
<pre><code>    internal class PropertyVisitor&lt;T&gt; : ExpressionVisitor
{
    public readonly List&lt;MemberInfo&gt; Path = new List&lt;MemberInfo&gt;();

    public Expression Modify(Expression expression)
    {
        return Visit(expression);
    }


    protected override Expression VisitMember(MemberExpression node)
    {
        if (!(node.Member is PropertyInfo))
        {
            throw new ArgumentException(&quot;The path can only contain properties&quot;, nameof(node));
        }

        Path.Add(node.Member);
        return  base.VisitMember(node);
    }
}
</code></pre>
<p><strong>Usages:</strong></p>
<p>Model Classes</p>
<pre><code>    public class Person
{
    public string Name { get; set; }
    public Address AddressDetail { get; set; }
}

public class Address
{
    public string Street { get; set; }
    public Country CountryDetail { get; set; }
    public Country[] CountryDetail2 { get; set; }
}

public class Country
{
    public string CountryName { get; set; }
    public Person[] CountryDetail { get; set; }
}
</code></pre>
